static void vli_mmod_fast_secp256r1(uint64_t *result, uint64_t *product) {
    uint64_t tmp[num_words_secp256r1];
    int carry;
    uECC_vli_set(result, product, num_words_secp256r1);
    /* s1 */
    tmp[0] = 0;
    tmp[1] = product[5] & 0xffffffff00000000ull;
    tmp[2] = product[6];
    tmp[3] = product[7];
    carry = (int)uECC_vli_add(tmp, tmp, tmp, num_words_secp256r1);
    carry += uECC_vli_add(result, result, tmp, num_words_secp256r1);
    /* s2 */
    tmp[1] = product[6] << 32;
    tmp[2] = (product[6] >> 32) | (product[7] << 32);
    tmp[3] = product[7] >> 32;
    carry += uECC_vli_add(tmp, tmp, tmp, num_words_secp256r1);
    carry += uECC_vli_add(result, result, tmp, num_words_secp256r1);
    /* s3 */ ... carry += uECC_vli_add(result, result, tmp, num_words_secp256r1);
    /* s4 */ ... carry += uECC_vli_add(result, result, tmp, num_words_secp256r1);
    /* d1..d4 */ ... carry -= uECC_vli_sub(result, result, tmp, num_words_secp256r1);
    if (carry < 0) {
        do {
            carry += uECC_vli_add(result, result, curve_secp256r1.p, num_words_secp256r1);
        } while (carry < 0);
    } else {
        while (carry || uECC_vli_cmp_unsafe(curve_secp256r1.p, result, num_words_secp256r1) != 1) {
            carry -= uECC_vli_sub(result, result, curve_secp256r1.p, num_words_secp256r1);
        }
    }
}
/* inner loop (uECC.c uECC_vli_add / uECC_vli_sub, inlined): */
for (i = 0; i < num_words; ++i) {
    uECC_word_t sum = left[i] + right[i] + carry;
    if (sum != left[i]) {
        carry = (sum < left[i]);
    }
    result[i] = sum;
}

for (k = 0; k < num_words; ++k) {
    for (i = 0; i <= k; ++i) {
        muladd(left[i], right[k - i], &r0, &r1, &r2);
    }
    result[k] = r0;
    r0 = r1;
    r1 = r2;
    r2 = 0;
}
for (k = num_words; k < num_words * 2 - 1; ++k) {
    for (i = (k + 1) - num_words; i < num_words; ++i) {
        muladd(left[i], right[k - i], &r0, &r1, &r2);
    }
    result[k] = r0;
    r0 = r1;
    r1 = r2;
    r2 = 0;
}
result[num_words * 2 - 1] = r0;
/* muladd (SUPPORTS_INT128 path): */
uECC_dword_t p = (uECC_dword_t)a * b;
uECC_dword_t r01 = ((uECC_dword_t)(*r1) << uECC_WORD_BITS) | *r0;
r01 += p;
*r2 += (r01 < p);
*r1 = r01 >> uECC_WORD_BITS;
*r0 = (uECC_word_t)r01;

uECC_word_t l_borrow = uECC_vli_sub(result, left, right, num_words);
if (l_borrow) {
    uECC_vli_add(result, result, mod, num_words);
}
/* uECC_vli_sub inner loop: */
for (i = 0; i < num_words; ++i) {
    uECC_word_t diff = left[i] - right[i] - borrow;
    if (diff != left[i]) {
        borrow = (diff > left[i]);
    }
    result[i] = diff;
}
